const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const store = {
get(key, fallback) { try { return JSON.parse(localStorage.getItem(`lr:${key}`)) ?? fallback; } catch { return fallback; } },
set(key, value) { try { localStorage.setItem(`lr:${key}`, JSON.stringify(value)); return true; } catch { return false; } }
};
const storedArray=(key,max=100)=>{const value=store.get(key,[]);return Array.isArray(value)?value.slice(0,max):[]};
let favorites = storedArray('favorites',500);
