const idFor = item => `${item.marketplace || ''}|${item.lien || item.url || ''}|${item.titre || item.title || ''}`;
const cleanText = value => String(value ?? '');
const safeUrl = value => { const raw=String(value||'').trim();if(!raw)return '#';try { const url=new URL(raw,location.origin); return ['http:','https:'].includes(url.protocol)?url.href:'#'; } catch { return '#'; } };
async function fetchWithTimeout(url,options={},timeout=15000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{return await fetch(url,{...options,signal:controller.signal,headers:{'Accept':'application/json',...(options.headers||{})}})}finally{clearTimeout(timer)}}
function initSearchUnderstanding(){
const configs=[
{input:'#marque',box:'#query-suggestions',hint:'#query-understanding',launch:false},
{input:'#global-search-input',box:'#global-query-suggestions',hint:'#global-query-understanding',launch:true},
{input:'#home-search-input',box:'#home-query-suggestions',hint:'#home-query-understanding',launch:true},
];
configs.forEach(config=>{
const input=$(config.input),box=$(config.box),hint=$(config.hint);if(!input||!box||!hint)return;
let timer=null,seq=0,active=-1,items=[];
const close=()=>{box.hidden=true;box.replaceChildren();items=[];active=-1;input.setAttribute('aria-expanded','false')};
const select=value=>{input.value=value;close();hint.textContent='';if(config.launch){prepareSimpleSearch(value);return}input.focus()};
const render=data=>{const current=String(input.value||'').trim(),understood=data?.understanding,catalogTotal=Number(data?.catalog_total||0);hint.replaceChildren();
if(understood?.corrected&&understood.canonical&&understood.canonical.toLowerCase()!==current.toLowerCase()){hint.append(document.createTextNode(tr('Recherche comprise comme : ','Understood as: ')));const strong=document.createElement('strong');strong.textContent=understood.canonical;hint.append(strong);if(catalogTotal>0)hint.append(document.createTextNode(tr(` · ${catalogTotal} offres déjà prêtes`,` · ${catalogTotal} offers already ready`)))}else if(catalogTotal>0){hint.textContent=tr(`${catalogTotal} offres déjà dans LUXE RADAR — affichage instantané`,`${catalogTotal} offers already in LUXE RADAR — instant display`)}
items=Array.isArray(data?.suggestions)?data.suggestions.slice(0,10):[];box.replaceChildren();active=-1;if(!items.length){box.hidden=true;input.setAttribute('aria-expanded','false');return}
if(catalogTotal>0){const summary=document.createElement('div');summary.className='query-suggestion-summary';summary.textContent=tr(`⚡ ${catalogTotal} offres indexées correspondent déjà`,`⚡ ${catalogTotal} indexed offers already match`);box.append(summary)}
items.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.className='query-suggestion';button.setAttribute('role','option');const main=document.createElement('span');main.className='query-suggestion-main';const label=document.createElement('b');label.textContent=String(item.label||item.value||'');const kind=document.createElement('small');kind.textContent=String(item.kind||'suggestion');main.append(label,kind);button.append(main);const meta=document.createElement('em');const count=Number(item.count||0),price=Number(item.price||0);meta.textContent=[count>0?tr(`${count} offre${count>1?'s':''}`,`${count} offer${count>1?'s':''}`):'',price>0?tr(`dès ${price.toFixed(2).replace('.',',')} €`,`from €${price.toFixed(2)}`):''].filter(Boolean).join(' · ');if(meta.textContent)button.append(meta);button.addEventListener('mousedown',event=>{event.preventDefault();select(String(item.value||item.label||''))});box.append(button)});box.hidden=false;input.setAttribute('aria-expanded','true')};
const requestSuggestions=()=>{clearTimeout(timer);const q=String(input.value||'').trim();if(q.length<2){close();hint.textContent='';return}const ticket=++seq;timer=setTimeout(async()=>{try{const response=await fetchWithTimeout(`/api/search-suggestions?q=${encodeURIComponent(q)}`,{},2500);if(!response.ok||ticket!==seq)return;render(await response.json())}catch{}},120)};
input.addEventListener('input',requestSuggestions);input.addEventListener('focus',()=>{if(String(input.value||'').trim().length>=2)requestSuggestions()});input.addEventListener('blur',()=>setTimeout(close,140));input.addEventListener('keydown',event=>{const buttons=$$('.query-suggestion',box);if(box.hidden||!buttons.length)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();active=(active+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons.forEach((b,i)=>b.classList.toggle('active',i===active));buttons[active]?.scrollIntoView({block:'nearest'})}else if(event.key==='Enter'&&active>=0){event.preventDefault();select(String(items[active]?.value||items[active]?.label||''))}else if(event.key==='Escape'){close()}});
});
}

