function translateLooseText(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement?.closest('script,style,[data-i18n]'))continue;const raw=node.nodeValue,trimmed=raw.trim();if(!trimmed)continue;if(node._lrFr===undefined)node._lrFr=trimmed;const value=settings.language==='en'?(textEn[node._lrFr]||node._lrFr):node._lrFr;if(value!==trimmed)node.nodeValue=raw.replace(trimmed,value)}$$('[placeholder]').forEach(el=>{if(el.dataset.frPlaceholder===undefined)el.dataset.frPlaceholder=el.placeholder;el.placeholder=settings.language==='en'?(placeholderEn[el.dataset.frPlaceholder]||el.dataset.frPlaceholder):el.dataset.frPlaceholder})}
const catalogStatusLabel=status=>({active:tr('Actif testé','Tested active'),to_test:tr('À tester','To test'),blocked:tr('Bloqué','Blocked'),non_implemented:tr('Non implémenté','Not implemented'),off:'OFF'})[status]||status;
const catalogStatusReason=status=>({active:tr('Recherche produit réellement validée.','Product search genuinely validated.'),to_test:tr('Domaine réel ; recherche produit à tester.','Real domain; product search still to test.'),blocked:tr('Accès public bloqué ou non concluant ; aucun contournement.','Public access blocked or inconclusive; no bypass.'),non_implemented:tr('Site réel ; aucun connecteur de recherche implémenté.','Real site; no search connector implemented.'),off:tr('Connecteur désactivé ; test produit non exploitable.','Connector disabled; product test not usable.')})[status]||'';
function catalogSiteNode(site){
const card=document.createElement('article');card.className='catalog-site';card.setAttribute('role','listitem');
const info=document.createElement('div'),title=document.createElement('h4'),domain=document.createElement('p'),meta=document.createElement('div');meta.className='catalog-site-meta';
title.textContent=cleanText(site.name||site.domain);domain.textContent=cleanText(site.domain);info.append(title,domain);
[site.category,site.country,site.currency].filter(Boolean).forEach(value=>{const chip=document.createElement('span');chip.textContent=cleanText(value);meta.append(chip)});
const capabilities=site.status==='active'?[site.supports_search&&tr('recherche','search'),site.supports_price&&tr('prix','price'),site.supports_image&&tr('image','image'),site.supports_reference&&tr('référence','reference')].filter(Boolean):[];
if(capabilities.length){const chip=document.createElement('span');chip.textContent=capabilities.join(' · ');meta.append(chip)}
info.append(meta);const reason=document.createElement('small');reason.className='catalog-reason';reason.textContent=catalogStatusReason(site.status);info.append(reason);
const side=document.createElement('div'),status=document.createElement('span');status.className='catalog-status';status.dataset.status=site.status;status.textContent=catalogStatusLabel(site.status);side.append(status);
const href=safeUrl(site.url);if(href!=='#'){const link=document.createElement('a');link.href=href;link.target='_blank';link.rel='noopener noreferrer';link.textContent='↗';link.ariaLabel=tr(`Visiter ${site.name}`,`Visit ${site.name}`);side.append(link)}
card.append(info,side);return card;
}
function renderCatalogSummary(data){const root=$('#catalog-summary');if(!root)return;root.replaceChildren();const entries=[[tr('Trouvés','Found'),data.total],[tr('ACTIFS','ACTIVE'),data.status_counts?.active||0],[tr('À TESTER','TO TEST'),data.status_counts?.to_test||0],[tr('NON IMPLÉMENTÉS','NOT IMPLEMENTED'),data.status_counts?.non_implemented||0],[tr('BLOQUÉS','BLOCKED'),data.status_counts?.blocked||0],['OFF',data.status_counts?.off||0]];entries.forEach(([label,value])=>{const chip=document.createElement('span');const strong=document.createElement('b');strong.textContent=String(value);chip.append(`${label} `,strong);root.append(chip)})}
async function loadCatalog(reset=false){if(catalogLoading||(!catalogHasMore&&!reset))return;catalogLoading=true;const list=$('#catalog-list'),more=$('#catalog-more'),status=$('#catalog-load-status');if(!list||!more||!status){catalogLoading=false;return}list.setAttribute('aria-busy','true');if(reset){catalogOffset=0;catalogHasMore=true;list.replaceChildren()}status.textContent=tr('Chargement du catalogue…','Loading catalogue…');const params=new URLSearchParams({offset:String(catalogOffset),q:$('#catalog-query')?.value.trim()||'',status:$('#catalog-status')?.value||'all',category:$('#catalog-category')?.value||'all'});try{const response=await fetchWithTimeout(`/api/catalog?${params}`,{},12000);if(!response.ok)throw new Error(tr('Catalogue indisponible','Catalogue unavailable'));const data=await response.json();if(reset&&!data.sites.length)list.append(emptyNode(tr('Aucun site trouvé','No sites found'),tr('Essaie un autre nom, statut ou catégorie.','Try another name, status or category.')));data.sites.forEach(site=>list.append(catalogSiteNode(site)));catalogOffset=data.next_offset;catalogHasMore=data.has_more;catalogHydrated=true;more.hidden=!catalogHasMore;const shown=list.querySelectorAll('.catalog-site').length;status.textContent=tr(`${shown} affichés sur ${data.total}`,`${shown} displayed out of ${data.total}`);renderCatalogSummary(data);const category=$('#catalog-category');if(category&&category.options.length===1){data.categories.forEach(name=>{const option=document.createElement('option');option.value=name;option.textContent=name;category.append(option)})}}catch(error){status.textContent=error.name==='AbortError'?tr('Le catalogue met trop de temps à répondre.','The catalogue took too long to respond.'):error.message;more.hidden=true}finally{list.setAttribute('aria-busy','false');catalogLoading=false}}
function hydrateCatalog(){if(!catalogHydrated)loadCatalog(true)}
