function syncLoadControls(){const manual=$('#manual-load-more'),status=$('#load-status'),size=Number($('#batch-size')?.value)||50,nextWave=!hasMore&&!expansionExhausted;if(manual){manual.hidden=!boot.token||loading||((settings.autoLoad&&!loadFailed)&&!nextWave);manual.textContent=loadFailed?tr('Réessayer le chargement','Retry loading'):nextWave?tr('Chercher une nouvelle vague','Fetch a new wave'):tr(`Charger ${size} résultats de plus`,`Load ${size} more results`)}if(status&&!loading&&!loadFailed&&boot.token&&!settings.autoLoad){if(hasMore)status.textContent=tr(`${$('#results-grid')?.children.length||0} affichés — utilise le bouton pour charger la suite`,`${$('#results-grid')?.children.length||0} displayed — use the button to load more`);else if(nextWave)status.textContent=tr('Fin du lot actuel — cherche une nouvelle vague de marketplaces.','End of current batch — fetch a new marketplace wave.')}}
function applySettings() {
const resolvedTheme=settings.theme==='system'?(systemTheme.matches?'light':'dark'):settings.theme;
if(!['lime','cyan','violet','rose','orange','blue','red','gold','mint'].includes(settings.accent))settings.accent='blue';
if(!['grid','list'].includes(settings.resultView))settings.resultView='grid';
document.documentElement.dataset.theme = resolvedTheme;
document.documentElement.dataset.accent = settings.accent;
document.body.classList.toggle('compact', settings.compact);
document.body.classList.toggle('radar-dense', Boolean(settings.radarDense));
document.body.classList.toggle('radar-focus', Boolean(settings.radarFocus));
document.body.classList.toggle('radar-list', settings.resultView==='list');
document.body.classList.toggle('reduced-motion', Boolean(settings.reducedMotion));
const metaTheme=$('#theme-color-meta');if(metaTheme)metaTheme.content=resolvedTheme==='light'?'#ffffff':'#11151b';
document.body.classList.remove('simple-mode','mode-essential','mode-expert','mode-reseller');
document.body.classList.add(`mode-${settings.experienceMode}`);
const compactSwitch=$('[data-setting="compact"]'),loadSwitch=$('[data-setting="autoLoad"]'),motionSwitch=$('[data-setting="reducedMotion"]');compactSwitch?.classList.toggle('on',settings.compact);compactSwitch?.setAttribute('aria-pressed',String(settings.compact));loadSwitch?.classList.toggle('on',settings.autoLoad);loadSwitch?.setAttribute('aria-pressed',String(settings.autoLoad));motionSwitch?.classList.toggle('on',Boolean(settings.reducedMotion));motionSwitch?.setAttribute('aria-pressed',String(Boolean(settings.reducedMotion)));const density=$('#density-toggle');if(density){density.textContent=settings.radarDense?tr('Vue confort','Comfort view'):tr('Vue dense','Dense view');density.classList.toggle('active',Boolean(settings.radarDense));density.setAttribute('aria-pressed',String(Boolean(settings.radarDense)))}const focus=$('#focus-toggle');if(focus){focus.textContent=settings.radarFocus?tr('Quitter focus','Exit focus'):tr('Mode focus','Focus mode');focus.classList.toggle('active',Boolean(settings.radarFocus));focus.setAttribute('aria-pressed',String(Boolean(settings.radarFocus)))}
$$('[data-theme-choice]').forEach(btn=>{const active=btn.dataset.themeChoice===settings.theme;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});
$$('[data-accent-choice]').forEach(btn=>{const active=btn.dataset.accentChoice===settings.accent;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});
$$('[data-result-view]').forEach(btn=>{const active=btn.dataset.resultView===settings.resultView;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});
const themeLabel = $('#theme-label'); if (themeLabel) themeLabel.textContent = settings.theme === 'system' ? (settings.language==='fr'?'Système':'System') : settings.theme === 'dark' ? (settings.language==='fr'?'Sombre':'Dark') : (settings.language==='fr'?'Clair':'Light');
const mode=$('#experience-toggle');if(mode){const labels={fr:{essential:['Mode Essentiel','Interface simplifiée'],expert:['Mode Expert','Tous les outils visibles'],reseller:['Mode Revendeur','Portfolio et marges en priorité']},en:{essential:['Essential mode','Simplified interface'],expert:['Expert mode','All tools visible'],reseller:['Reseller mode','Portfolio and margins first']}}[settings.language];$('span',mode).textContent=labels[settings.experienceMode][0];$('small',mode).textContent=labels[settings.experienceMode][1];mode.ariaLabel=settings.language==='fr'?`Changer de mode. Mode actuel : ${labels[settings.experienceMode][0]}`:`Change mode. Current: ${labels[settings.experienceMode][0]}`}
applyLanguage();
syncLoadControls();
}
function refreshSubscription(){if(subscription.trialEnds&&new Date(subscription.trialEnds)<=new Date()){subscription={plan:'free',trialEnds:null};store.set('subscription',subscription)}const planName=subscription.plan==='reseller'?'PRO':subscription.plan==='pro'?'PREMIUM':tr('GRATUIT','FREE');const badge=$('#current-plan');if(badge)badge.textContent=planName;const detail=$('#plan-detail');if(detail)detail.textContent=subscription.trialEnds?`${tr('Essai jusqu’au','Trial until')} ${new Date(subscription.trialEnds).toLocaleDateString(settings.language==='en'?'en-GB':'fr-FR')}`:tr('Plan actuel','Current plan');$$('.plan-cta').forEach(btn=>{const current=btn.dataset.plan===subscription.plan;btn.disabled=current;if(current)btn.textContent=tr('Plan actuel','Current plan');else if(boot.billingReady&&btn.dataset.plan!=='free')btn.textContent=btn.dataset.plan==='pro'?tr('Choisir Premium','Choose Premium'):tr('Choisir Pro','Choose Pro')});const pricingEyebrow=$('.pricing-hero .eyebrow'),pricingCopy=$('.pricing-hero p');if(pricingEyebrow&&pricingCopy){pricingEyebrow.textContent=boot.billingReady?tr('PAIEMENT SÉCURISÉ ACTIF','SECURE PAYMENT ACTIVE'):tr('OFFRE EN PRÉPARATION · PAIEMENT DÉSACTIVÉ','OFFER IN PREPARATION · PAYMENTS DISABLED');pricingCopy.textContent=boot.billingReady?tr('Prévisualise les offres. Le paiement sécurisé est actif via Stripe.','Preview the offers. Secure payment is active via Stripe.'):tr('Prévisualise les offres envisagées. Aucun débit ni abonnement réel n’est actuellement déclenché.','Preview the proposed offers. No payment or real subscription is currently triggered.')}const popularBadge=$('.price-card.featured .popular');if(popularBadge)popularBadge.textContent=boot.billingReady?tr('ABONNEMENT STRIPE','STRIPE SUBSCRIPTION'):tr('OFFRE ENVISAGÉE','PROPOSED OFFER');const trialNote=$('.price-card.featured .trial-note');if(trialNote)trialNote.textContent=boot.billingReady?tr('Essai local de 7 jours inclus · paiement Stripe sécurisé','7-day local trial included · secure Stripe payment'):tr('Démo locale 7 jours · aucun paiement','7-day local demo · no payment');const faqSub=$('.faq-subscription');if(faqSub)faqSub.textContent=boot.billingReady?tr('Oui, le paiement est sécurisé via Stripe (mode test : aucun débit réel). L’essai local de 7 jours reste gratuit.','Yes, payment is securely handled by Stripe (test mode: no real charge). The 7-day local trial remains free.'):tr('Non actuellement. Les tarifs présentent l’offre envisagée ; le débit reste désactivé jusqu’au branchement sécurisé d’un prestataire de paiement.','Not currently. The prices present the proposed offer; billing stays disabled until a secure payment provider is connected.')}
function navigate(view, updateHash = true) {
const safe = ['dashboard','radar','favorites','alerts','discover','studio','portfolio','pricing','history','settings','data'].includes(view) ? view : 'dashboard';
$$('.view').forEach(x => x.classList.toggle('active', x.id === `view-${safe}`));
$$('.nav-button').forEach(x => x.classList.toggle('active', x.dataset.view === safe));
$$('.nav-button').forEach(x=>x.setAttribute('aria-current',x.dataset.view===safe?'page':'false'));
const titles = {...(pageTitles[settings.language] || pageTitles.fr),data:settings.language==='en'?['Data','Export, restore or erase your local data.']:['Données','Exporte, restaure ou efface tes données locales.']};
$('#page-title').textContent = titles[safe][0]; $('#page-subtitle').textContent = titles[safe][1];
if(updateHash)announce(`${titles[safe][0]}. ${titles[safe][1]}`);
if (updateHash && location.hash !== `#${safe}`) window.history.pushState({view:safe}, '', `#${safe}`);
document.body.classList.toggle('radar-focus',safe==='radar'&&Boolean(settings.radarFocus));
if (safe === 'favorites') renderFavorites();
if (safe === 'alerts') renderAlerts();
if (safe === 'studio') renderStudio();
if (safe === 'portfolio') renderPortfolio();
if (safe === 'history') renderHistory();
if (safe === 'data') renderDataSummary();
if (safe === 'discover') {hydrateCatalog()}
applyLanguage();
}
function makeCard(item) {
const itemId=idFor(item);
const article = document.createElement('article'); article.className = 'product-card'; article.dataset.id = itemId;article.dataset.price=cleanText(item.prix);article.dataset.market=cleanText(item.marketplace||'');article.dataset.risk=cleanText(item.risque_contrefacon||'faible');article.dataset.identity=cleanText(item.niveau_identite||'possible');
const media = document.createElement('div'); media.className = 'product-image';
const imageUrl=safeUrl(item.image);if (imageUrl!=='#') { const img = document.createElement('img'); img.src = imageUrl; img.alt = cleanText(item.titre || item.title); img.loading = 'lazy'; img.decoding='async'; img.referrerPolicy='no-referrer'; img.addEventListener('error',()=>{const none=document.createElement('span');none.className='no-image';none.textContent=tr('Image indisponible','Image unavailable');media.replaceChildren(none)},{once:true});media.append(img); }
else { const none = document.createElement('span'); none.className='no-image'; none.textContent=tr('Image indisponible','Image unavailable'); media.append(none); }
const fav = document.createElement('button'); fav.className='favorite-btn'; fav.type='button'; fav.ariaLabel=tr('Ajouter aux favoris','Add to favorites'); fav.textContent='♡'; fav.addEventListener('click', () => toggleFavorite(item, fav));
const body = document.createElement('div'); body.className='product-body';
const top = document.createElement('div'); top.className='product-top';
const badge = document.createElement('span'); badge.className='badge'; badge.textContent=cleanText(item.marketplace || 'Marketplace');
const price = document.createElement('strong'); price.className='product-price'; price.textContent=`${cleanText(item.prix)} ${cleanText(item.devise || '€')}`;
top.append(badge, price);
const title = document.createElement('h3'); title.className='product-title'; title.textContent=cleanText(item.titre || item.title || tr('Annonce','Listing'));
const metrics=document.createElement('div');metrics.className='metrics';const metricParts=[],scoreValue=item.score===''?NaN:Number(item.score),confidenceValue=item.score_confiance===''?NaN:Number(item.score_confiance),imageSimilarity=Number(item.similarite_image);if(Number.isFinite(scoreValue))metricParts.push(`Score ${Math.round(scoreValue)}`);if(Number.isFinite(confidenceValue))metricParts.push(`${tr('Confiance','Confidence')} ${Math.round(confidenceValue)}%`);if(Number.isFinite(imageSimilarity))metricParts.push(`${tr('Image','Image')} ${Math.round(imageSimilarity)}%`);metrics.textContent=metricParts.join(' · ')||tr('Données partielles','Partial data');
const link=document.createElement('a'),listingUrl=safeUrl(item.lien||item.url);link.className='product-link';link.href=listingUrl;if(listingUrl==='#'){link.classList.add('disabled');link.setAttribute('aria-disabled','true');link.textContent=tr('Lien indisponible','Link unavailable');link.addEventListener('click',event=>event.preventDefault())}else{link.target='_blank';link.rel='noopener noreferrer';link.textContent=tr('Voir l’annonce ↗','View listing ↗');link.addEventListener('click',()=>recordViewed(item))}
const compare=document.createElement('button');compare.className='compare-action';compare.type='button';const compared=comparison.some(x=>idFor(x)===idFor(item));compare.textContent=compared?tr('✓ Dans le comparateur','✓ In comparison'):tr('⇄ Comparer','⇄ Compare');compare.classList.toggle('selected',compared);compare.setAttribute('aria-pressed',String(compared));compare.onclick=()=>toggleCompare(item,compare);
const track=document.createElement('button');track.className='track-action';track.type='button';track.textContent=tr('Enregistrer ce prix','Record this price');track.addEventListener('click',()=>recordListingPrice(item));
const verifyRow=document.createElement('div');verifyRow.className='verification-row';const identity=document.createElement('span');identity.className=`identity-badge ${article.dataset.identity}`;identity.textContent=article.dataset.identity==='fort'?tr('Match exact','Exact match'):article.dataset.identity==='rejet'?tr('À vérifier','Needs review'):tr('Match probable','Probable match');const risk=document.createElement('span');risk.className=`auth-risk ${article.dataset.risk}`;risk.textContent=article.dataset.risk==='eleve'?tr('Risque élevé','High risk'):article.dataset.risk==='modere'?tr('Authenticité à vérifier','Verify authenticity'):tr('Aucun signal détecté','No explicit signal detected');risk.title=cleanText(item.alerte_authenticite||'');verifyRow.append(identity,risk);
const relevance=document.createElement('details');relevance.className='match-explain';const summary=document.createElement('summary');summary.textContent=tr('Pourquoi ce résultat ?','Why this result?');const explain=document.createElement('p');explain.textContent=cleanText(item.explication_pertinence||tr('Le moteur a comparé la marque, le modèle et les mots de la requête.','The engine compared the brand, model and query terms.'));if(item.conflit_pertinence){const conflict=document.createElement('small');conflict.textContent=`${tr('Attention','Caution')} : ${cleanText(item.conflit_pertinence)}`;relevance.append(summary,explain,conflict)}else relevance.append(summary,explain);
const dismiss=document.createElement('button');dismiss.className='dismiss-action';dismiss.type='button';dismiss.textContent=tr('× Hors sujet','× Not relevant');dismiss.addEventListener('click',()=>{hiddenResults.add(itemId);store.set('hiddenResults',[...hiddenResults].slice(-500));article.remove();updateHiddenResultCount();const shown=$$('#results-grid .product-card').length;if($('#shown-count'))$('#shown-count').textContent=shown;toast(tr('Annonce masquée. Tu peux la restaurer depuis les filtres rapides.','Listing hidden. You can restore it from quick filters.'))});
const actionRow=document.createElement('div');actionRow.className='card-actions';actionRow.append(link,compare,dismiss);
body.append(top,verifyRow,title,metrics,relevance,actionRow,track); article.append(media,fav,body); syncFavoriteButton(fav,item); if(hiddenResults.has(itemId))article.classList.add('user-hidden'); return article;
}
function syncFavoriteButton(btn,item){const saved=favorites.some(x=>idFor(x)===idFor(item));btn.classList.toggle('saved',saved);btn.textContent=saved?'♥':'♡';btn.setAttribute('aria-pressed',String(saved));btn.ariaLabel=saved?(settings.language==='fr'?'Retirer des favoris':'Remove from favorites'):(settings.language==='fr'?'Ajouter aux favoris':'Add to favorites')}
function syncAllFavoriteButtons(){ $$('.product-card').forEach(card=>{const btn=$('.favorite-btn',card); const saved=favorites.some(x=>idFor(x)===card.dataset.id);btn?.classList.toggle('saved',saved);if(btn){btn.textContent=saved?'♥':'♡';btn.setAttribute('aria-pressed',String(saved));btn.ariaLabel=saved?(settings.language==='fr'?'Retirer des favoris':'Remove from favorites'):(settings.language==='fr'?'Ajouter aux favoris':'Add to favorites')}}); updateCounters(); }
function toggleFavorite(item){const id=idFor(item), index=favorites.findIndex(x=>idFor(x)===id);if(index>=0)favorites.splice(index,1);else{favorites.unshift(item);addActivity(`Favori ajouté : ${item.titre||item.title||'Annonce'}`)}store.set('favorites',favorites);if($('#view-favorites')?.classList.contains('active'))renderFavorites();syncAllFavoriteButtons();updateCounters();if(clientQuickFilters.favoritesOnly)applyClientQuickFilters()}
function renderFavorites(){const grid=$('#favorites-grid'),count=$('#favorite-visible-count');grid.replaceChildren();if(!favorites.length){if(count)count.textContent=tr('0 favori','0 favorites');grid.append(emptyNode(tr('Aucun favori pour le moment','No favorites yet'),tr('Clique sur le cœur d’une annonce pour la retrouver ici.','Select the heart on a listing to find it here.')));return}const query=($('#favorite-query')?.value||'').trim().toLocaleLowerCase(settings.language),sort=$('#favorite-sort')?.value||'recent';let items=favorites.filter(item=>!query||`${item.titre||item.title||''} ${item.marketplace||''}`.toLocaleLowerCase(settings.language).includes(query));if(sort==='price_asc')items.sort((a,b)=>(Number(a.prix)||Infinity)-(Number(b.prix)||Infinity));else if(sort==='price_desc')items.sort((a,b)=>(Number(b.prix)||-1)-(Number(a.prix)||-1));else if(sort==='marketplace')items.sort((a,b)=>String(a.marketplace||'').localeCompare(String(b.marketplace||''),settings.language));if(count)count.textContent=tr(`${items.length} affichés / ${favorites.length}`,`${items.length} displayed / ${favorites.length}`);if(!items.length){grid.append(emptyNode(tr('Aucun favori correspondant','No matching favorites'),tr('Essaie un autre nom ou une autre marketplace.','Try another name or marketplace.')));return}items.forEach(item=>grid.append(makeCard(item)))}
function emptyNode(title,copy){const div=document.createElement('div');div.className='empty';const strong=document.createElement('strong');strong.textContent=title;const span=document.createElement('span');span.textContent=copy;div.append(strong,span);return div}
function renderHistory(){const list=$('#history-list');list.replaceChildren();if(!history.length){list.append(emptyNode(tr('Aucune recherche enregistrée','No saved searches'),tr('Tes recherches apparaîtront ici automatiquement.','Your searches will appear here automatically.')));return}history.forEach(item=>{const row=document.createElement('div');row.className='history-item';const info=document.createElement('div');const strong=document.createElement('strong');strong.textContent=item.query;const meta=document.createElement('div');meta.className='muted';meta.textContent=`${item.price?`≤ ${item.price} €` : tr('Tous les prix','All prices')} · ${item.marketplace}${item.reference?` · ${tr('réf.','ref.')} ${item.reference}${item.strictReference?` (${tr('strict','strict')})`:''}`:''} · ${new Date(item.date).toLocaleString(settings.language==='en'?'en-GB':'fr-FR')}`;info.append(strong,meta);const btn=document.createElement('button');btn.className='ghost-btn';btn.textContent=tr('Relancer','Run again');btn.onclick=()=>{navigate('radar');$('#marque').value=item.query;$('#prix').value=item.price;$('#plateforme').value=item.marketplace;if($('#reference-exacte'))$('#reference-exacte').value=item.reference||'';if($('#reference-stricte'))$('#reference-stricte').checked=Boolean(item.strictReference)};row.append(info,btn);list.append(row)})}
function recordViewed(item){const id=idFor(item);recentlyViewed=recentlyViewed.filter(entry=>idFor(entry)!==id);recentlyViewed.unshift({...item,viewedAt:new Date().toISOString()});recentlyViewed=recentlyViewed.slice(0,50);store.set('recentlyViewed',recentlyViewed);renderRecentlyViewed()}
