trackers.forEach((item,index)=>trackerList.append(trackerRowNode(item,index)));
const inv=$('#inventory-list');
inv.replaceChildren();
let invested=0,profit=0;
inventory.forEach(item=>{invested+=Number(item.buy)||0;if(item.status==='Vendu')profit+=(Number(item.sell)||0)-(Number(item.buy)||0)});const inventoryQuery=($('#inventory-query')?.value||'').trim().toLocaleLowerCase(settings.language),inventoryStatus=$('#inventory-filter')?.value||'all',visibleInventory=inventory.map((item,index)=>({item,index})).filter(({item})=>(!inventoryQuery||cleanText(item.name).toLocaleLowerCase(settings.language).includes(inventoryQuery))&&(inventoryStatus==='all'||item.status===inventoryStatus));visibleInventory.forEach(({item,index})=>{const statusEn={'En stock':'In stock','En vente':'For sale','Vendu':'Sold'}[item.status]||item.status;inv.append(rowNode(item.name,`${settings.language==='en'?statusEn:item.status} · ${tr('achat','buy')} ${item.buy} €${item.sell!==null&&item.sell!==undefined?` · ${tr('vente','sale')} ${item.sell} €`:''}`,()=>{inventory.splice(index,1);store.set('inventory',inventory);renderPortfolio()}))});if($('#inventory-visible-count'))$('#inventory-visible-count').textContent=tr(`${visibleInventory.length} affichés / ${inventory.length}`,`${visibleInventory.length} displayed / ${inventory.length}`);if(!visibleInventory.length&&inventory.length)inv.append(emptyNode(tr('Aucun article correspondant','No matching item'),tr('Essaie un autre nom ou statut.','Try another name or status.')));
